App.toggleMark = function(s) {
	var g = App.G;
	if(g.phase != "threats") {
		return;
	}
	var i = g.marks.indexOf(s);
	if(i >= 0) {
		g.marks.splice(i,1);
	} else {
		g.marks.push(s);
	}
	App.drawGame();
};
