App.eliteTag = function(from,group) {
	if(UiJs.cur == null || UiJs.cur.children == null) {
		return;
	}
	var items = UiJs.cur.children;
	var ti = from;
	while(ti < items.length) {
		var it = items[ti];
		it.dataset.eliteGroup = group;
		it.dataset.eliteIndex = Std.string(ti - from);
		++ti;
	}
};
App.hanging = function(p,side) {
	var out = [];
	var b = p.board;
	var _g = 0;
	while(_g < 64) {
		var sq = _g++;
		var pc = b[sq];
		if(pc == 0 || (pc > 0 ? 1 : pc < 0 ? -1 : 0) != side || (pc < 0 ? -pc : pc) == 6) {
			continue;
		}
		if(!Engine.isAttacked(b,sq,-side)) {
			continue;
		}
		b[sq] = -pc;
		var defended = Engine.isAttacked(b,sq,side);
		b[sq] = pc;
		if(!defended) {
			out.push(sq);
		}
	}
	return out;
};
App.movesText = function(sans) {
	var s = "";
	var _g = 0;
	var _g1 = sans.length;
	while(_g < _g1) {
		var i = _g++;
		if(i % 2 == 0) {
			s += (i / 2 | 0) + 1 + ". ";
		}
		s += sans[i] + " ";
	}
	return StringTools.trim(s);
};
