Drills.check = function(uci) {
	var r = Drills.R;
	var t = Drills.task();
	var k = t.k;
	if(k == "pz") {
		var mv = t.moves;
		var exp = mv[r.step];
		var ok = uci == exp || r.step == mv.length - 1 && Drills.isMateAfter(uci);
		if(!ok) {
			Drills.fail("Não é isso.");
			return;
		}
		var s = App.san(Engine.toFEN(r.pos),uci);
		if(r.shownFen != null) {
			r.log.push("Você: " + s);
		}
		Drills.autoMoveUser(uci);
		if(r.step >= mv.length) {
			Drills.solved(r.shownFen != null ? "Correto! Você calculou a linha inteira." : "Correto!");
			return;
		}
		r.state = "wait";
		Drills.draw();
		var g = r.gen;
		UiJs.later(r.opts.storm == true ? 200 : 450,function() {
			if(Drills.R != r || r.gen != g) {
				return;
			}
			Drills.autoMove(mv[r.step]);
			r.state = "play";
			Drills.draw();
		});
		return;
	}
	if(k == "q") {
		var acc = t.accept;
		if(acc.indexOf(uci) >= 0) {
			Drills.autoMoveUser(uci);
			Drills.solved("Correto!");
		} else {
			var _g = [];
			var _g1 = 0;
			while(_g1 < acc.length) {
				var a = acc[_g1];
				++_g1;
				_g.push(App.san(t.fen,a));
			}
			Drills.fail("Não é o lance esperado. Bons lances aqui: " + _g.join(", ") + ".");
		}
		return;
	}
	if(k == "mine") {
		if(uci == t.best) {
			Drills.autoMoveUser(uci);
			Drills.solved("Correto! Esse é o lance mais indicado.");
			return;
		}
		r.judging = true;
		Drills.draw();
		var g1 = r.gen;
		Think.run({ cmd : "judge", fen : t.fen, uci : uci},function(j) {
			if(Drills.R != r || r.gen != g1) {
				return;
			}
			r.judging = false;
			var loss = j.loss;
			if(loss <= 3) {
				Drills.autoMoveUser(uci);
				Drills.solved("Muito bom: tão bom quanto o lance indicado (" + App.san(t.fen,t.best) + ").");
			} else {
				Drills.fail("Ainda não. O mais indicado era " + App.san(t.fen,t.best) + ".");
			}
		});
		return;
	}
	if(k == "line") {
		var ucis = t.ucis;
		var exp = ucis[r.step];
		if(uci != exp) {
			r.failed = true;
			var tmp = "No seu repertório o lance é " + App.san(Engine.toFEN(r.pos),exp);
			r.msg = tmp + " (seta). Jogue-o para continuar.";
			r.cls = "warn";
			var tmp = App.arrow(exp,0);
			r.arrows = [tmp];
			Drills.draw();
			return;
		}
		r.arrows = [];
		r.msg = "";
		Drills.autoMoveUser(uci);
		if(r.step < ucis.length) {
			Drills.autoMove(ucis[r.step]);
		}
		if(r.step >= ucis.length) {
			if(r.failed) {
				r.state = "fail";
				r.msg = "Linha concluída com erro: ela volta amanhã.";
				r.cls = "warn";
				Drills.record(false);
				Drills.draw();
			} else {
				Drills.solved("Linha completa sem erros!");
			}
			return;
		}
		Drills.draw();
	}
};
Drills.autoMoveUser = function(uci) {
	var r = Drills.R;
	var m = Engine.uciToMove(r.pos,uci);
	if(m < 0) {
		return;
	}
	Engine.makeMove(r.pos,m);
	r.pos.stack = [];
	r.step++;
	if(r.shownFen == null) {
		r.last = App.lastOf(uci);
	}
};
Drills.solved = function(msg) {
	var r = Drills.R;
	if(r.failed) {
		r.state = "fail";
		r.msg = "Resolvido, mas com dica: conta como erro e volta para revisão.";
		r.cls = "warn";
		Drills.record(false);
	} else {
		r.state = "ok";
		r.msg = msg;
		r.cls = "good";
		Drills.record(true);
	}
	if(r.opts.storm == true) {
		Drills.stormNext(r.state == "ok");
		return;
	}
	if(r.opts.rush == true) {
		Drills.rushNext(r.state == "ok");
		return;
	}
	Drills.draw();
};
Drills.fail = function(msg) {
	var r = Drills.R;
	r.state = "fail";
	r.msg = msg;
	r.cls = "bad";
	r.failed = true;
	Drills.record(false);
	if(r.opts.storm == true) {
		Drills.stormNext(false);
		return;
	}
	if(r.opts.rush == true) {
		Drills.rushNext(false);
		return;
	}
	var t = Drills.task();
	if(t.k == "pz" && r.shownFen == null) {
		var mv = t.moves;
		if(r.step < mv.length) {
			r.arrows = [App.arrow(mv[r.step],0)];
		}
	}
	if(t.k == "q") {
		var acc = t.accept;
		r.arrows = [App.arrow(acc[0],0)];
	}
	if(t.k == "mine") {
		r.arrows = [App.arrow(t.best,0)];
	}
	Drills.draw();
};
Drills.record = function(ok) {
	var r = Drills.R;
	var t = Drills.task();
	var k = t.k;
	var ms = HxOverrides.now() / 1000 * 1000 - r.t0;
	r.res.push({ id : t.id, ok : ok, ms : ms, dim : t.dim, rating : t.rating, k : k});
	if(r.opts.storm == true || r.opts.rush == true) {
		return;
	}
	if(r.opts.placement == true) {
		Profile.touch();
		return;
	}
	if(t.srs == true) {
		Profile.srsResult(k == "line" ? "rep" : k,t.id,ok);
		if(k == "pz") {
			Profile.addDim("tatica",ok);
			var tg = t.tags;
			var _g = 0;
			while(_g < tg.length) {
				var x = tg[_g];
				++_g;
				Profile.addTheme(x,ok);
			}
		}
		return;
	}
	if(k == "pz") {
		Profile.recordPuzzle(t.id,t.rating,ok,t.tags,ms);
	} else if(k == "line") {
		Profile.srsAdd("rep",t.id,null);
		if(ok) {
			Profile.srsResult("rep",t.id,true);
		}
		Profile.addDim("abertura",ok);
		Profile.save();
	} else {
		Profile.addDim(t.dim,ok);
		Profile.addDim("tempo",ok && ms <= 45000);
		Profile.touch();
		Profile.save();
	}
};
Drills.hint = function() {
	var r = Drills.R;
	var t = Drills.task();
	var k = t.k;
	r.failed = true;
	var u = null;
	if(k == "pz") {
		u = t.moves[r.step];
	} else if(k == "q") {
		u = t.accept[0];
	} else if(k == "mine") {
		u = t.best;
	}
	if(u != null) {
		r.marks = [[Engine.nameSq(HxOverrides.substr(u,0,2)),3]];
	}
	r.msg = "Dica: a peça destacada é a que deve se mover. (Dica conta como erro e o exercício volta para revisão.)";
	r.cls = "warn";
	if(k == "pz") {
		var tags = t.tags;
		var bm = Content.bestMotif(tags);
		if(bm != null) {
			r.msg += " Tema: " + Content.themeName(bm) + ".";
		}
	}
	Drills.draw();
};
Drills.giveUp = function() {
	var r = Drills.R;
	if(r.opts.placement == true) {
		Drills.fail("Sem problema: vamos para a próxima.");
		return;
	}
	Drills.fail("Veja a solução.");
};
Drills.next = function() {
	var r = Drills.R;
	if(r.i >= r.tasks.length - 1) {
		Drills.finishRun();
		return;
	}
	r.i++;
	Drills.startTask();
};
Drills.replay = function() {
	var r = Drills.R;
	var t = Drills.task();
	var g = ++r.gen;
	r.pos = Engine.posFromFEN(t.fen);
	r.step = 0;
	r.shownFen = null;
	r.arrows = [];
	r.marks = [];
	r.log = [];
	var mv = t.moves;
	var st = r.state;
	r.state = "show";
	Drills.draw();
	var i = 0;
	var stepFn = null;
	stepFn = function() {
		if(Drills.R != r || r.gen != g) {
			return;
		}
		if(i >= mv.length) {
			r.state = st;
			Drills.draw();
			return;
		}
		Drills.autoMove(mv[i]);
		i += 1;
		Drills.draw();
		UiJs.later(800,stepFn);
	};
	UiJs.later(500,stepFn);
};
Drills.finishRun = function() {
	var r = Drills.R;
	Drills.R = null;
	UiJs.cancel(r.timer);
	if(r.opts.done != null) {
		r.opts.done(r.res);
		return;
	}
	Drills.summary(r.title,r.res,r.opts.back);
};
Drills.summary = function(title,res,back) {
	var ok = 0;
	var _g = 0;
	while(_g < res.length) {
		var x = res[_g];
		++_g;
		if(x.ok) {
			++ok;
		}
	}
	UiJs.page(title,back);
	UiJs.p("Você acertou " + ok + " de " + res.length + ".","big gold");
	UiJs.p("Pontuação de quebra-cabeças: " + Std.string(Profile.d.pzElo),"");
	if(ok < res.length) {
		UiJs.p("Os que você errou voltam para revisão no momento certo para fixar (Táticas › Revisões do dia).","muted");
	}
	UiJs.btns([["Voltar",back,"pri"]]);
};
Drills.rushNext = function(ok) {
	var r = Drills.R;
	if(ok) {
		r.score++;
		r.rating += 60;
	} else {
		r.lives--;
	}
	if(r.lives <= 0) {
		Drills.R = null;
		var best = Profile.d.rushBest;
		var rec = r.score > best;
		if(rec) {
			Profile.d.rushBest = r.score;
		}
		Profile.touch();
		Profile.save();
		UiJs.page("Puzzle Rush",r.opts.back);
		UiJs.p(r.score + " acertos" + (rec ? " · novo recorde!" : ""),"big gold");
		UiJs.p("Chegou até o nível " + r.rating + ". Recorde: " + Std.string(Profile.d.rushBest) + ".","");
		UiJs.btns([["Jogar de novo",function() {
			Drills.run("Puzzle Rush",[Study.stormTask(Math.max(400,Profile.d.pzElo - 500) | 0,null)],r.opts);
		},"pri"],["Voltar",r.opts.back]]);
		return;
	}
	if(!ok) {
		r.msg = "Errou: restam " + r.lives + (r.lives == 1 ? " vida." : " vidas.");
	}
	var avoid = new haxe_ds_StringMap();
	var _g = 0;
	var _g1 = r.res;
	while(_g < _g1.length) {
		var x = _g1[_g];
		++_g;
		avoid.h[x.id] = true;
	}
	r.tasks.push(Study.stormTask(r.rating,avoid));
	var keep = r.msg;
	r.i++;
	Drills.startTask();
	if(!ok) {
		r.msg = keep;
		r.cls = "bad";
		Drills.draw();
	}
};
Drills.stormLeft = function() {
	var ms = Drills.R.stormEnd - HxOverrides.now() / 1000 * 1000;
	if(ms < 0) {
		ms = 0;
	}
	var s = ms / 1000 | 0;
	return (s / 60 | 0) + ":" + (s % 60 < 10 ? "0" : "") + s % 60;
};
Drills.stormTick = function() {
	var r = Drills.R;
	if(r == null || r.opts.storm != true) {
		return;
	}
	if(HxOverrides.now() / 1000 * 1000 >= r.stormEnd) {
		Drills.stormEnd();
		return;
	}
	UiJs.bars("Puzzle Storm · " + Drills.stormLeft(),(r.color == 1 ? "Brancas" : "Pretas") + " jogam  ·  " + r.score + " pts",true,true);
};
Drills.stormNext = function(ok) {
	var r = Drills.R;
	if(ok) {
		r.score++;
		r.streak++;
		r.rating += 35;
	} else {
		r.streak = 0;
		r.errors++;
		r.stormEnd -= 10000;
		r.rating -= 20;
	}
	var avoid = new haxe_ds_StringMap();
	var _g = 0;
	var _g1 = r.res;
	while(_g < _g1.length) {
		var x = _g1[_g];
		++_g;
		avoid.h[x.id] = true;
	}
	r.tasks.push(Study.stormTask(r.rating,avoid));
	r.i++;
	Drills.startTask();
};
Drills.stormEnd = function() {
	var r = Drills.R;
	if(r == null) {
		return;
	}
	Drills.R = null;
	UiJs.cancel(r.timer);
	r.gen++;
	var best = Profile.d.stormBest;
	var rec = r.score > best;
	if(rec) {
		Profile.d.stormBest = r.score;
	}
	Profile.addDim("tempo",r.score >= 10);
	Profile.touch();
	Profile.save();
	UiJs.page("Puzzle Storm",r.opts.back);
	UiJs.p(r.score + " acertos em 3 minutos" + (rec ? " · novo recorde!" : ""),"big gold");
	UiJs.p("Erros: " + r.errors + " (cada erro custa 10 segundos). Recorde: " + Std.string(Profile.d.stormBest) + ".","");
	if(r.opts.done != null) {
		var d = r.opts.done;
		UiJs.btns([["Continuar",function() {
			d(r.res);
		},"pri"]]);
	} else {
		UiJs.btns([["Jogar de novo",function() {
			Drills.run("Puzzle Storm",[Study.stormTask(Math.max(400,Profile.d.pzElo - 350) | 0,null)],r.opts);
		},"pri"],["Voltar",r.opts.back]]);
	}
};
Drills.endgame = function(id,back,done) {
	var eg = Content.endgame(id);
	var pos = Engine.posFromFEN(eg.fen);
	Drills.E = { eg : eg, pos : pos, human : eg.human, keys : [Engine.posKey(pos)], moves : 0, busy : null, msg : "", cls : "", over : null, back : back, done : done, last : null, hint : null, gen : 0};
	UiJs.boardPage(eg.name,back);
	if(pos.turn != Drills.E.human) {
		Drills.egCpu();
	} else {
		Drills.egDraw();
	}
};
Drills.goalText = function(eg) {
	var n = eg.moves;
	switch(eg.goal) {
	case "draw":
		return "Objetivo: segurar o empate por " + n + " lances (ou forçar empate antes).";
	case "mate":
		return "Objetivo: dar xeque-mate em até " + n + " lances.";
	case "promote":
		return "Objetivo: promover o peão (e manter a nova dama) em até " + n + " lances.";
	default:
		return "Objetivo: vencer. Dê mate ou chegue ao lance " + n + " com vantagem decisiva.";
	}
};
Drills.egDraw = function() {
	var e = Drills.E;
	var b = UiJs.board;
	var eg = e.eg;
	if(b == null) {
		return;
	}
	b.fen = Engine.toFEN(e.pos);
	b.flip = e.human == -1;
	b.last = e.last;
	b.check = App.checkSq(e.pos);
	b.arrows = e.hint != null ? [App.arrow(e.hint,3)] : [];
	b.marks = [];
	b.blind = false;
	b.onSquare = null;
	b.legal = e.over == null && e.busy == null && e.pos.turn == e.human ? App.legalUcis(e.pos) : null;
	b.onMove = Drills.egMove;
	b.clearSel();
	b.draw();
	UiJs.bars("Motor (defesa perfeita)","Você · lance " + e.moves + " de " + Std.string(eg.moves),e.pos.turn != e.human,e.pos.turn == e.human);
	UiJs.panel();
	UiJs.p(Drills.goalText(eg),"gold");
	UiJs.p(eg.tip,"");
	if(e.busy != null) {
		UiJs.p(e.busy,"muted");
	}
	if(e.msg != "") {
		UiJs.p(e.msg,e.cls);
	}
	var bs = [];
	if(e.over == null) {
		bs.push(["Dica",Drills.egHint,e.busy == null ? "" : "off"]);
	}
	bs.push(["Recomeçar",function() {
		Drills.endgame(eg.id,e.back,e.done);
	},e.over != null && e.over == false ? "pri" : ""]);
	if(e.over == true && e.done != null) {
		bs.push(["Continuar",function() {
			e.done(true);
		},"pri"]);
	}
	bs.push(["Sair",function() {
		Drills.E = null;
		if(e.done != null && e.over != true) {
			e.done(false);
		} else {
			e.back();
		}
	}]);
	UiJs.btns(bs);
};
Drills.egEnd = function(ok,msg) {
	var e = Drills.E;
	e.over = ok;
	e.msg = msg;
	e.cls = ok ? "good" : "bad";
	e.busy = null;
	Profile.addDim("finais",ok);
	if(ok) {
		Profile.setEgDone(e.eg.id);
	} else {
		Profile.touch();
		Profile.save();
	}
	Drills.egDraw();
};
Drills.egMove = function(u4) {
	var e = Drills.E;
	if(e.over != null || e.busy != null || e.pos.turn != e.human) {
		return;
	}
	App.pickPromo(App.legalUcis(e.pos),u4,function(uci) {
		var m = Engine.uciToMove(e.pos,uci);
		var promo = uci.length > 4;
		Engine.makeMove(e.pos,m);
		e.pos.stack = [];
		e.keys.push(Engine.posKey(e.pos));
		e.last = App.lastOf(uci);
		e.moves++;
		e.hint = null;
		e.msg = "";
		var eg = e.eg;
		var goal = eg.goal;
		var st = Engine.gameStatus(e.pos,e.keys);
		if(st.over) {
			if(st.winner == e.human) {
				Drills.egEnd(true,"Xeque-mate! Objetivo cumprido em " + e.moves + " lances.");
				return;
			}
			if(goal == "draw") {
				Drills.egEnd(true,"Empate (" + App.howText(st.result) + "). Objetivo cumprido!");
				return;
			}
			Drills.egEnd(false,"Empate (" + App.howText(st.result) + "): " + (st.result == "stalemate" ? "cuidado com o afogamento! Deixe sempre uma casa livre para o rei." : "a vantagem escapou."));
			return;
		}
		if(goal == "promote" && promo) {
			e.busy = "Conferindo a posição…";
			Drills.egDraw();
			Think.run({ cmd : "eval", fen : Engine.toFEN(e.pos), keys : e.keys, nodes : 30000},function(r) {
				if(Drills.E != e) {
					return;
				}
				var sc = r.score;
				if(sc <= -400) {
					Drills.egEnd(true,"Promoveu e a vantagem é decisiva. Objetivo cumprido!");
				} else {
					Drills.egEnd(false,"Promoveu, mas a nova peça se perde ou a vantagem sumiu. Tente proteger a casa de promoção antes.");
				}
			});
			return;
		}
		Drills.egCpu();
	});
};
Drills.egCpu = function() {
	var e = Drills.E;
	e.busy = "O motor está pensando…";
	Drills.egDraw();
	Think.run({ cmd : "eg", fen : Engine.toFEN(e.pos), keys : e.keys},function(r) {
		if(Drills.E != e || e.over != null) {
			return;
		}
		e.busy = null;
		if(r.uci == null) {
			Drills.egDraw();
			return;
		}
		var m = Engine.uciToMove(e.pos,r.uci);
		var promo = r.uci.length > 4;
		Engine.makeMove(e.pos,m);
		e.pos.stack = [];
		e.keys.push(Engine.posKey(e.pos));
		e.last = App.lastOf(r.uci);
		var eg = e.eg;
		var goal = eg.goal;
		var lim = eg.moves;
		var st = Engine.gameStatus(e.pos,e.keys);
		if(st.over) {
			if(st.winner == -e.human) {
				Drills.egEnd(false,"Você levou mate.");
				return;
			}
			if(goal == "draw") {
				Drills.egEnd(true,"Empate (" + App.howText(st.result) + "). Objetivo cumprido!");
				return;
			}
			Drills.egEnd(false,"Empate (" + App.howText(st.result) + "): a vitória escapou.");
			return;
		}
		if(promo && goal == "draw") {
			Drills.egEnd(false,"O peão adversário promoveu.");
			return;
		}
		if(e.moves >= lim) {
			if(goal == "mate" || goal == "promote") {
				Drills.egEnd(false,"Acabaram os " + lim + " lances. Tente um plano mais direto (veja a dica do texto).");
				return;
			}
			e.busy = "Conferindo a posição…";
			Drills.egDraw();
			Think.run({ cmd : "eval", fen : Engine.toFEN(e.pos), keys : e.keys, nodes : 30000},function(rr) {
				if(Drills.E != e) {
					return;
				}
				var sc = rr.score;
				if(goal == "draw") {
					if(sc >= -150) {
						Drills.egEnd(true,"Você segurou " + lim + " lances e a posição continua empatada. Objetivo cumprido!");
					} else {
						Drills.egEnd(false,"Você chegou ao lance " + lim + ", mas a posição ficou perdida.");
					}
				} else if(sc >= 500) {
					Drills.egEnd(true,"A vitória está garantida (vantagem decisiva). Objetivo cumprido!");
				} else {
					Drills.egEnd(false,"A vantagem diminuiu demais. Tente de novo trocando peças e avançando os peões.");
				}
			});
			return;
		}
		Drills.egDraw();
	});
};
Drills.egHint = function() {
	var e = Drills.E;
	if(e.busy != null || e.over != null) {
		return;
	}
	e.busy = "Procurando o melhor lance…";
	Drills.egDraw();
	Think.run({ cmd : "eg", fen : Engine.toFEN(e.pos), keys : e.keys},function(r) {
		if(Drills.E != e) {
			return;
		}
		e.busy = null;
		e.hint = r.uci;
		e.msg = r.uci != null ? "Sugestão do motor: " + Std.string(r.san) : "";
		e.cls = "gold";
		Drills.egDraw();
	});
};
Drills.model = function(g,side,back) {
	Drills.M = { g : g, side : side, ply : 0, pos : Engine.posFromFEN("rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1"), pts : 0, max : 0, n : 0, msg : "", cls : "", busy : false, back : back, arrows : [], last : null, gen : 0, imb : null, wait : false, done : false};
	UiJs.boardPage(g.name(),back);
	if(side == 0) {
		Drills.mDraw();
		return;
	}
	var start = g.moves.length > 24 ? 10 : 4;
	while(Drills.M.ply < start || Drills.M.ply < g.moves.length && Drills.M.pos.turn != side) Drills.mStep();
	Drills.mDraw();
};
Drills.mStep = function() {
	var g = Drills.M.g;
	if(Drills.M.ply >= g.moves.length) {
		return;
	}
	var u = g.moves[Drills.M.ply];
	var m = Engine.uciToMove(Drills.M.pos,u);
	if(m < 0) {
		Drills.M.ply = g.moves.length;
		return;
	}
	Engine.makeMove(Drills.M.pos,m);
	Drills.M.pos.stack = [];
	Drills.M.last = App.lastOf(u);
	Drills.M.ply++;
};
Drills.mGoto = function(n) {
	var g = Drills.M.g;
	if(n < 0) {
		n = 0;
	}
	if(n > g.moves.length) {
		n = g.moves.length;
	}
	Drills.M.pos = Engine.posFromFEN("rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1");
	Drills.M.ply = 0;
	Drills.M.last = null;
	while(Drills.M.ply < n) Drills.mStep();
	Drills.M.imb = null;
	Drills.M.arrows = [];
	Drills.mDraw();
};
Drills.mDraw = function() {
	var g = Drills.M.g;
	var b = UiJs.board;
	if(b == null) {
		return;
	}
	var guess = Drills.M.side != 0;
	b.fen = Engine.toFEN(Drills.M.pos);
	b.flip = Drills.M.side == -1;
	b.last = Drills.M.last;
	b.check = App.checkSq(Drills.M.pos);
	b.arrows = Drills.M.arrows;
	b.marks = [];
	b.blind = false;
	b.onSquare = null;
	b.legal = guess && !Drills.M.busy && !Drills.M.wait && !Drills.M.done && Drills.M.pos.turn == Drills.M.side ? App.legalUcis(Drills.M.pos) : null;
	b.onMove = Drills.mGuess;
	b.clearSel();
	b.draw();
	UiJs.bars(ModelGame.short(g.black) + " (Pretas)",ModelGame.short(g.white) + " (Brancas) · " + g.year,Drills.M.pos.turn == -1,Drills.M.pos.turn == 1);
	if(Drills.M.side == -1) {
		UiJs.bars(ModelGame.short(g.white) + " (Brancas) · " + g.year,ModelGame.short(g.black) + " (Pretas)",Drills.M.pos.turn == 1,Drills.M.pos.turn == -1);
	}
	UiJs.panel();
	if(g.desc != "") {
		UiJs.p(g.desc,"muted");
	}
	var op = Book.detect(g.moves.slice(0,Drills.M.ply));
	if(Drills.M.ply > 0 && Drills.M.ply <= g.evals.length) {
		var mp = Drills.M.ply;
		var ev = g.evals[mp - 1];
		App.chanceOf(ev);
	}
	if(guess) {
		var pct = Drills.M.max > 0 ? Math.round(Drills.M.pts * 100 / Drills.M.max) : 0;
		UiJs.p("Adivinhe o lance de " + (Drills.M.side == 1 ? "Brancas" : "Pretas") + " · pontos " + Std.string(Drills.M.pts) + " de " + Std.string(Drills.M.max) + " (" + pct + "%)","gold");
		UiJs.p("2 pontos = lance do mestre · 1 ponto = outro lance tão bom quanto, segundo o motor · 0 = pior.","muted small");
		if(Drills.M.busy) {
			UiJs.p("Conferindo seu palpite…","muted");
		}
		if(Drills.M.msg != "") {
			UiJs.p(Drills.M.msg,Drills.M.cls);
		}
		if(Drills.M.done) {
			var perf = Study.guessPerf(pct);
			UiJs.p("Fim da partida (" + g.result + "). Desempenho estimado: " + perf + " (aproximação pelo percentual de pontos).","big gold");
			UiJs.btns([["Voltar",Drills.M.back,"pri"]]);
		} else {
			UiJs.btns([Drills.M.wait ? ["Continuar",Drills.mAdvance,"pri"] : null,["Desequilíbrios",Drills.mImb],["Sair",Drills.M.back]]);
		}
	} else {
		UiJs.p("Lance " + Std.string(Drills.M.ply) + " de " + g.moves.length + (Drills.M.ply > 0 ? " · " + Drills.lastSan() : ""),"gold");
		UiJs.btns([["⏮",function() {
			Drills.mGoto(0);
		}],["◀",function() {
			Drills.mGoto(Drills.M.ply - 1);
		}],["▶",function() {
			Drills.mGoto(Drills.M.ply + 1);
		},"pri"],["⏭",function() {
			Drills.mGoto(g.moves.length);
		}]]);
		UiJs.btns([["Desequilíbrios",Drills.mImb],["Sair",Drills.M.back]]);
	}
	if(Drills.M.imb != null) {
		UiJs.h("Desequilíbrios (Silman) para " + (Drills.M.pos.turn == 1 ? "Brancas" : "Pretas"));
		var rows = Drills.M.imb.rows;
		var _g = 0;
		while(_g < rows.length) {
			var r = rows[_g];
			++_g;
			UiJs.p(Std.string(r[0]) + ": " + Std.string(r[2]),r[1] == 1 ? "good" : r[1] == -1 ? "bad" : "");
		}
		UiJs.ul(Drills.M.imb.plan);
	}
	if(op != null) {
		UiJs.p("Abertura: " + op[1] + " (" + op[0] + ")","muted small");
	}
	UiJs.p(g.white + " x " + g.black + " · " + g.year + " · " + g.result,"muted small");
};
Drills.lastSan = function() {
	var g = Drills.M.g;
	var p = Engine.posFromFEN("rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1");
	var s = "";
	var _g = 0;
	var _g1 = Drills.M.ply;
	while(_g < _g1) {
		var i = _g++;
		var m = Engine.uciToMove(p,g.moves[i]);
		if(i == Drills.M.ply - 1) {
			s = (p.turn == 1 ? p.full + ". " : p.full + "… ") + Engine.moveToSAN(p,m);
		}
		Engine.makeMove(p,m);
	}
	return s;
};
Drills.mImb = function() {
	if(Drills.M.imb != null) {
		Drills.M.imb = null;
		Drills.mDraw();
		return;
	}
	var m = Drills.M;
	Think.run({ cmd : "imb", fen : Engine.toFEN(Drills.M.pos), color : Drills.M.pos.turn},function(r) {
		if(Drills.M != m) {
			return;
		}
		m.imb = r;
		Drills.mDraw();
	});
};
Drills.mGuess = function(u4) {
	var m = Drills.M;
	if(m.busy || m.wait || m.done) {
		return;
	}
	App.pickPromo(App.legalUcis(m.pos),u4,function(uci) {
		var g = m.g;
		var master = g.moves[m.ply];
		var fen = Engine.toFEN(m.pos);
		var mSan = App.san(fen,master);
		m.max += 2;
		m.n++;
		if(uci == master) {
			m.pts += 2;
			m.msg = "+2 · Exatamente o lance do mestre: " + mSan + ".";
			m.cls = "good";
			var tmp = App.arrow(master,0);
			m.arrows = [tmp];
			m.wait = true;
			Drills.mDraw();
			return;
		}
		m.busy = true;
		Drills.mDraw();
		Think.run({ cmd : "judge", fen : fen, uci : uci},function(j) {
			if(Drills.M != m) {
				return;
			}
			m.busy = false;
			var loss = j.loss;
			if(loss <= 3) {
				m.pts += 1;
				var tmp = "+1 · " + App.san(fen,uci) + " também é bom, segundo o motor. O mestre jogou " + mSan;
				m.msg = tmp + ".";
				m.cls = "gold";
			} else {
				var tmp = "0 · " + App.san(fen,uci) + " perde " + App.pctTxt(loss) + " de chance. O mestre jogou " + mSan;
				m.msg = tmp + ".";
				m.cls = "bad";
			}
			var tmp = App.arrow(uci,1);
			var tmp1 = App.arrow(master,0);
			m.arrows = [tmp,tmp1];
			m.wait = true;
			Drills.mDraw();
		});
	});
};
Drills.mAdvance = function() {
	var m = Drills.M;
	var g = m.g;
	m.wait = false;
	m.arrows = [];
	m.msg = "";
	Drills.mStep();
	if(m.ply < g.moves.length) {
		Drills.mStep();
	}
	if(m.ply >= g.moves.length || m.ply == g.moves.length - 1 && m.pos.turn != m.side) {
		while(m.ply < g.moves.length && m.pos.turn != m.side) Drills.mStep();
	}
	if(m.ply >= g.moves.length) {
		m.done = true;
		var pct = m.max > 0 ? m.pts * 100 / m.max : 0;
		var md = Profile.d.model;
		md.push({ g : g.idx, side : m.side, pct : Math.round(pct), perf : Study.guessPerf(pct), n : m.n, t : new Date().getTime()});
		while(md.length > 60) md.shift();
		Profile.touch();
		Profile.save();
	}
	Drills.mDraw();
};
Drills.explorer = function(color,back) {
	Drills.X = { pos : Engine.posFromFEN("rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1"), color : color, ucis : [], msg : "", cls : "", last : null, arrows : [], hits : 0, n : 0, back : back, end : false};
	UiJs.boardPage("Jogue como os mestres",back);
	if(color == -1) {
		Drills.xAuto();
	}
	Drills.xDraw();
};
Drills.xAuto = function() {
	var u = Book.pickMaster(Drills.X.pos,0.05,1.0);
	if(u == null) {
		Drills.X.end = true;
		return;
	}
	var m = Engine.uciToMove(Drills.X.pos,u);
	Engine.makeMove(Drills.X.pos,m);
	Drills.X.pos.stack = [];
	Drills.X.ucis.push(u);
	Drills.X.last = App.lastOf(u);
	if(Book.masterMoves(Drills.X.pos) == null) {
		Drills.X.end = true;
	}
};
Drills.xDraw = function() {
	var b = UiJs.board;
	b.fen = Engine.toFEN(Drills.X.pos);
	b.flip = Drills.X.color == -1;
	b.last = Drills.X.last;
	b.check = -1;
	b.arrows = Drills.X.arrows;
	b.marks = [];
	b.blind = false;
	b.onSquare = null;
	b.legal = Drills.X.end ? null : App.legalUcis(Drills.X.pos);
	b.onMove = Drills.xMove;
	b.clearSel();
	b.draw();
	UiJs.bars("Base de mestres","Acertos " + Std.string(Drills.X.hits) + " de " + Std.string(Drills.X.n),false,true);
	UiJs.panel();
	var op = Book.detect(Drills.X.ucis);
	if(op != null) {
		UiJs.p(op[1] + " (" + op[0] + ")","gold");
	}
	UiJs.p(Drills.X.end ? "Fim da teoria da base nesta linha. Recomece para explorar outra." : "Jogue um lance que os mestres jogam nesta posição.","");
	if(Drills.X.msg != "") {
		UiJs.p(Drills.X.msg,Drills.X.cls);
	}
	var mm = Book.masterMoves(Drills.X.pos);
	if(mm != null && Drills.X.arrows.length > 0) {
		var rows = [];
		var _g = 0;
		var _g1 = mm.slice(0,4);
		while(_g < _g1.length) {
			var x = _g1[_g];
			++_g;
			rows.push(App.san(Engine.toFEN(Drills.X.pos),x[0]) + ": " + Math.round(x[2] * 100) + "% das partidas (Brancas " + Std.string(x[3]) + "% · empate " + Std.string(x[4]) + "% · Pretas " + Std.string(x[5]) + "%)");
		}
		UiJs.ul(rows);
		var sf = Book.sfMoves(Drills.X.pos);
		if(sf != null) {
			UiJs.p("Stockfish 19 prefere " + App.san(Engine.toFEN(Drills.X.pos),sf[0][0]) + ".","muted");
		}
	}
	UiJs.btns([["Recomeçar",function() {
		Drills.explorer(Drills.X.color,Drills.X.back);
	},Drills.X.end ? "pri" : ""],["Trocar de cor",function() {
		Drills.explorer(-Drills.X.color,Drills.X.back);
	}],["Sair",Drills.X.back]]);
};
Drills.xMove = function(u4) {
	App.pickPromo(App.legalUcis(Drills.X.pos),u4,function(uci) {
		var mm = Book.masterMoves(Drills.X.pos);
		var share = 0.0;
		if(mm != null) {
			var _g = 0;
			while(_g < mm.length) {
				var x = mm[_g];
				++_g;
				if(x[0] == uci) {
					share = x[2];
				}
			}
		}
		Drills.X.n++;
		if(share >= 0.05) {
			Drills.X.hits++;
			Drills.X.arrows = [];
			var tmp = App.san(Engine.toFEN(Drills.X.pos),uci) + ": jogado em ";
			Drills.X.msg = tmp + Math.round(share * 100) + "% das partidas de mestres.";
			Drills.X.cls = "good";
			var m = Engine.uciToMove(Drills.X.pos,uci);
			Engine.makeMove(Drills.X.pos,m);
			Drills.X.pos.stack = [];
			Drills.X.ucis.push(uci);
			Drills.X.last = App.lastOf(uci);
			if(Book.masterMoves(Drills.X.pos) == null) {
				Drills.X.end = true;
			} else {
				Drills.xAuto();
			}
			Profile.addDim("abertura",true);
		} else {
			Drills.X.msg = "Mestres quase não jogam esse lance aqui. Veja o que eles preferem:";
			Drills.X.cls = "warn";
			var tmp;
			if(mm == null) {
				tmp = [];
			} else {
				var _g = [];
				var _g1 = 0;
				var _g2 = mm.slice(0,3);
				while(_g1 < _g2.length) {
					var x = _g2[_g1];
					++_g1;
					_g.push(App.arrow(x[0],2));
				}
				tmp = _g;
			}
			Drills.X.arrows = tmp;
			Profile.addDim("abertura",false);
		}
		Profile.save();
		Drills.xDraw();
	});
};
