Pages.stageTask = function(i,j) {
	var s = Content.trail()[i];
	var t = s.tasks[j];
	var tp = t.t;
	var back = function() {
		Pages.stage(i);
	};
	var mark = function() {
		var pr = Profile.trailState(i).prog;
		pr[j] = 1;
		Profile.save();
	};
	switch(tp) {
	case "calc":case "pz":
		Drills.run(t.label,Study.trailTasks(i,j),{ back : back, done : function(res) {
			var ok = 0;
			var _g = 0;
			while(_g < res.length) {
				var x = res[_g];
				++_g;
				if(x.ok) {
					++ok;
				}
			}
			var pass = ok >= Math.ceil(res.length * 0.75);
			if(pass) {
				mark();
			}
			UiJs.page(t.label,back);
			UiJs.p("Você acertou " + ok + " de " + res.length + ".","big " + (pass ? "good" : "bad"));
			UiJs.p(pass ? "Exercício concluído!" : "Precisa de 75% para concluir. Os erros voltam nas revisões; tente de novo com outros problemas.","");
			var tmp = pass ? null : ["Tentar de novo",function() {
				Pages.stageTask(i,j);
			}];
			UiJs.btns([["Voltar à etapa",back,"pri"],tmp]);
		}});
		break;
	case "eg":
		Drills.endgame(t.id,back,function(ok) {
			back();
		});
		break;
	case "md":
		Pages.modelCat(t.cat);
		break;
	case "rep":
		if(Study.myReps().length == 0) {
			UiJs.toast("Primeiro escolha seu repertório.");
			Pages.openings();
			return;
		}
		var tasks = Study.repDue(3);
		if(tasks.length == 0) {
			var rs = Study.myReps();
			var _g = [];
			_g.push(Study.repTask(rs[0 % rs.length],0 / rs.length | 0));
			_g.push(Study.repTask(rs[1 % rs.length],1 / rs.length | 0));
			_g.push(Study.repTask(rs[2 % rs.length],2 / rs.length | 0));
			tasks = _g;
		}
		Drills.run("Repertório",tasks,{ back : back, done : function(res) {
			mark();
			back();
		}});
		break;
	case "st":
		var seen = Profile.d.stSeen == null ? [] : Profile.d.stSeen;
		if(seen.length >= t.n) {
			mark();
			back();
			return;
		}
		UiJs.toast("Estude " + Std.string(t.n) + " estruturas (já estudou " + seen.length + ").");
		Pages.structs();
		break;
	default:
		back();
	}
};
Pages.exam = function(i) {
	var back = function() {
		Pages.stage(i);
	};
	Drills.run("Prova · " + Std.string(Content.trail()[i].name),Study.trailExam(i),{ back : back, done : function(res) {
		var ok = 0;
		var _g = 0;
		while(_g < res.length) {
			var x = res[_g];
			++_g;
			if(x.ok) {
				++ok;
			}
		}
		var ts = Profile.trailState(i);
		if(ok > ts.best) {
			ts.best = ok;
		}
		var pass = ok >= 8;
		if(pass) {
			ts.exam = true;
		}
		Profile.touch();
		Profile.save();
		UiJs.page("Resultado da prova",back);
		UiJs.p(ok + " de " + res.length + (pass ? " · aprovado!" : " · ainda não"),"big " + (pass ? "good" : "bad"));
		UiJs.p(pass ? i < 5 ? "Etapa concluída. A próxima está liberada." : "Você concluiu a trilha inteira. Agora é jogar partidas e torneios!" : "Precisa de " + 8 + " acertos. Revise as lições e os erros (eles voltam nas revisões) e tente de novo.","");
		UiJs.btns([["Voltar à trilha",Pages.trail,"pri"]]);
	}});
};
