Pages.wood = function() {
	var w = Study.woodSet();
	var times = w.times;
	var scores = w.scores;
	var ids = w.ids;
	var n = ids.length;
	UiJs.page("Woodpecker",Pages.tactics);
	UiJs.p("Método dos pica-paus (Smith e Tikkanen): resolva o mesmo conjunto várias vezes. A meta de cada ciclo é a metade do tempo do anterior, sem perder acertos: os padrões viram reflexo.","muted");
	UiJs.p("Conjunto atual: " + (w.name != null ? w.name : "Misto no seu nível") + " · " + n + " problemas","gold");
	var last = times.length > 0 ? times[times.length - 1] : 0.0;
	var goal = last > 0 ? Math.max(15000.0 * Math.max(1,n / 10),last / 2) : 0.0;
	var st = [[times.length == null ? "null" : "" + times.length,times.length == 1 ? "ciclo feito" : "ciclos feitos"]];
	if(last > 0) {
		st.push([Pages.fmtT(last),"último ciclo"]);
	}
	if(goal > 0) {
		st.push([Pages.fmtT(goal),"meta do próximo"]);
	}
	UiJs.stats(st);
	var _g = 0;
	var _g1 = times.length;
	while(_g < _g1) {
		var i = _g++;
		var ok = i == 0 || times[i] <= times[i - 1] / 2 + 30000;
		UiJs.p("Ciclo " + (i + 1) + ": " + scores[i] + "/" + n + " em " + Pages.fmtT(times[i]) + (i > 0 ? ok ? " · meta batida" : " · acima da meta" : ""),i > 0 && ok ? "good" : "");
	}
	if(times.length >= 6 || times.length >= 3 && last <= 60000 * Math.max(1,n / 15)) {
		UiJs.p("Este conjunto já está automático. Comece um novo para aprender outros padrões.","good");
	}
	UiJs.btns([["Começar ciclo " + (times.length + 1),function() {
		var t0 = HxOverrides.now() / 1000 * 1000;
		Drills.run("Woodpecker · ciclo " + (times.length + 1),Study.woodTasks(),{ back : Pages.wood, done : function(res) {
			var ok = 0;
			var _g = 0;
			while(_g < res.length) {
				var x = res[_g];
				++_g;
				if(x.ok) {
					++ok;
				}
			}
			if(res.length >= n) {
				times.push(HxOverrides.now() / 1000 * 1000 - t0);
				scores.push(ok);
				w.cycle = times.length;
				Profile.save();
			}
			Pages.wood();
		}});
	},"pri"],["Novo conjunto",Pages.woodNew]]);
};
Pages.fmtT = function(ms) {
	var sec = Math.round(ms / 1000);
	if(sec < 60) {
		return sec + " s";
	}
	var m = Math.floor(sec / 60);
	var r = sec - m * 60;
	if(m < 10 && r > 0) {
		return m + " min " + r + " s";
	} else {
		return Math.round(sec / 60) + " min";
	}
};
