Pages.lineSan = function(ucis) {
	var p = Engine.posFromFEN("rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1");
	var out = [];
	var _g = 0;
	while(_g < ucis.length) {
		var u = ucis[_g];
		++_g;
		var m = Engine.uciToMove(p,u);
		if(m < 0) {
			break;
		}
		out.push((p.turn == 1 ? p.full + "." : "") + Engine.moveToSAN(p,m));
		Engine.makeMove(p,m);
	}
	return out.join(" ");
};
