		while(_g < _g1.length) {
			var sec = [_g1[_g]];
			++_g;
			var items = [sec[0][1]];
			UiJs.group("rsec",(function(items,sec) {
				return function() {
					UiJs.p(sec[0][0],"gold");
					if(items[0].length > 0) {
						UiJs.ul(items[0],"small");
					} else {
						UiJs.p(sec[0][2],"muted");
					}
				};
			})(items,sec));
		}
		UiJs.h("Evolução mês a mês");
		Evo.monthly(v);
		UiJs.h("Como evoluir cada característica");
		var order = ax.slice();
		order.sort(function(a,b) {
			var x = a.val < 0 ? 999 : a.val;
			var y = b.val < 0 ? 999 : b.val;
			return Reflect.compare(x,y);
		});
		var _g = [];
