	var prefix = true;
	var _g = 0;
	var _g1 = Math.min(known.length,ucis.length) | 0;
	while(_g < _g1) {
		var i = _g++;
		if(known[i] != ucis[i]) {
			prefix = false;
			break;
		}
	}
	var o = g.me == 1 ? x.b : x.w;
	var myo = Online.opp(g);
	if(o.n != null && o.n != "") {
		myo.n = o.n;
	}
	if(o.e != null && o.e > 0) {
		myo.e = o.e;
	}
	if(o.p != null && o.p != "") {
		myo.p = o.p;
	}
	if(!prefix) {
		UiJs.modal("A partida recebida não confere","Os lances recebidos são diferentes dos que estão salvos aqui. Qual versão vale?",[["Usar a recebida",function() {
			g.ucis = ucis;
			g.r = x.r;
			g.d = x.d;
			g.sent = true;
			g.res = null;
			Online.store(g);
			Online.finalize(g);
			Online.show(g);
		},"pri"],["Manter a minha",function() {
			Online.show(g);
		}]]);
		return;
	}
	if(ucis.length < known.length || ucis.length == known.length && (x.r == null || x.r == "") && x.d == g.d) {
		Online.show(g);
		UiJs.toast(ucis.length < known.length ? "Esse link é de uma jogada antiga. Mostrando a posição mais recente." : "Nenhuma novidade nessa jogada.");
		return;
	}
	g.ucis = ucis;
	g.r = x.r;
	g.d = x.d;
	g.t = x.t;
	g.sent = true;
	Online.store(g);
	Online.finalize(g);
	Online.show(g);
