			var d = rc[1] - rc[0];
			UiJs.p("Amigos (WhatsApp): " + (rc[0] == 0 ? "" : rc[0] + " → ") + rc[1] + (rc[0] == 0 ? "" : " (" + (d >= 0 ? "+" : "") + d + ")") + (Profile.isProvisional("online") ? " · provisória" : ""),"gold");
