History.fersSvg = function() {
	var s_b = "";
	s_b += "<svg viewBox=\"0 0 400 214\" role=\"img\" aria-label=\"Alcance da fers medieval e da dama moderna\">";
	var _g = 0;
	while(_g < 2) {
		var k = _g++;
		var ox = 12 + k * 200;
		var oy = 8;
		var c = 22;
		var _g1 = 0;
		while(_g1 < 8) {
			var r = _g1++;
			var _g2 = 0;
			while(_g2 < 8) {
				var f = _g2++;
				var dk = (r + f & 1) == 1;
				var df = f - 3;
				var dr = r - 4;
				var reach = k == 0 ? Math.abs(df) == 1 && Math.abs(dr) == 1 : (df == 0 || dr == 0 || Math.abs(df) == Math.abs(dr)) && !(df == 0 && dr == 0);
				s_b += Std.string("<rect x=\"" + (ox + f * c) + "\" y=\"" + (oy + r * c) + "\" width=\"" + c + "\" height=\"" + c + "\" fill=\"" + (dk ? "#8f5f37" : "#ead9b0") + "\"/>");
				if(reach) {
					s_b += Std.string("<circle cx=\"" + (ox + f * c + c / 2) + "\" cy=\"" + (oy + r * c + c / 2) + "\" r=\"5.5\" fill=\"" + (k == 0 ? "#e3605a" : "#4cb871") + "\" opacity=\".9\"/>");
				}
			}
		}
		var x = ox + 3 * c + c / 2;
		var y = oy + 4 * c + c / 2;
		s_b += Std.string("<circle cx=\"" + x + "\" cy=\"" + y + "\" r=\"9\" fill=\"#f3d98c\" stroke=\"#3a2212\" stroke-width=\"2\"/>");
		s_b += Std.string("<rect x=\"" + ox + "\" y=\"" + oy + "\" width=\"" + 8 * c + "\" height=\"" + 8 * c + "\" fill=\"none\" stroke=\"#3a2510\" stroke-width=\"2\"/>");
		s_b += Std.string("<text x=\"" + (ox + 4 * c) + "\" y=\"" + (oy + 8 * c + 16) + "\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"700\" fill=\"" + (k == 0 ? "#e3605a" : "#4cb871") + "\">" + (k == 0 ? "Fers medieval: 4 casas" : "Dama desde 1475: 27 casas") + "</text>");
	}
	s_b += "</svg>";
	return s_b;
};
