Content.EXTRA_CURIOS = ["O mate mais rápido possível acontece no segundo lance: 1.f3 e5 2.g4 Dh4#. É o chamado mate do louco.","Depois de dois lances de cada lado já existem 197.281 partidas diferentes possíveis. O motor deste jogo confere esse número nos testes.","A partida oficial mais longa foi Nikolić x Arsović, em Belgrado (1989): 269 lances e mais de 20 horas de jogo. Terminou empatada.","O Comitê Olímpico Internacional reconhece o xadrez como esporte desde 1999, e a Olimpíada de Xadrez entre países é disputada desde 1927.","Em 2024, o indiano Gukesh Dommaraju tornou-se, aos 18 anos, o mais jovem campeão mundial de xadrez clássico.","A Partida Imortal (Anderssen x Kieseritzky, 1851) e a Partida do Século (Byrne x Fischer, 1956) estão na biblioteca de partidas-modelo deste jogo."];
Content.THEMES = [["mateIn1","Mate em 1","Um lance dá xeque-mate. Procure xeques que tiram todas as casas do rei."],["mateIn2","Mate em 2","Dois lances até o mate; o primeiro força a resposta (xeque ou ameaça forte)."],["mateIn3","Mate em 3","Sequência forçada de três lances. Calcule as respostas forçadas a cada xeque."],["backRankMate","Mate no corredor","O rei preso na primeira fila pelos próprios peões leva mate de torre ou dama."],["smotheredMate","Mate sufocado","O cavalo dá mate num rei cercado pelas próprias peças."],["fork","Garfo","Uma peça ataca duas ao mesmo tempo; o adversário só salva uma."],["pin","Cravada","A peça não pode sair sem expor o rei ou uma peça maior."],["skewer","Espeto","Ataque em linha: a peça valiosa da frente sai e a de trás cai."],["discoveredAttack","Ataque descoberto","Mover uma peça libera o ataque de outra que estava atrás dela."],["doubleCheck","Xeque duplo","Duas peças dão xeque ao mesmo tempo: só o rei pode se mover."],["hangingPiece","Peça pendurada","Capture a peça adversária sem defesa suficiente."],["sacrifice","Sacrifício","Entregue material para ganhar algo maior: mate ou mais material."],["promotion","Promoção","O peão chega à última fila e vira dama (ou outra peça)."],["opening","Tática na abertura","Golpes que aparecem nos primeiros lances, quando o rei ainda está no centro."],["middlegame","Meio-jogo","Táticas com muitas peças no tabuleiro."],["endgame","Final","Táticas com poucas peças: rei ativo, peões passados e promoção."],["oneMove","Um lance","A solução tem um único lance seu."],["short","Curto","Dois lances seus."],["long","Longo","Três lances seus: calcule a linha inteira antes de mover."],["veryLong","Muito longo","Quatro ou mais lances seus."],["advantage","Vantagem","A solução ganha material ou uma vantagem decisiva (não é mate)."],["mate","Mate","A solução termina em xeque-mate."],["mateIn4","Mate em 4","Quatro lances até o mate. Ache o primeiro xeque ou ameaça que tira a liberdade do rei."],["mateIn5","Mate em 5 ou mais","Combinações longas de mate: calcule xeque por xeque."],["anastasiaMate","Mate de Anastácia","Cavalo e torre (ou dama) prendem o rei na coluna da borda, bloqueado pelo próprio peão."],["arabianMate","Mate árabe","Torre e cavalo no canto: o cavalo protege a torre e cobre a casa de fuga."],["bodenMate","Mate de Boden","Dois bispos em diagonais cruzadas dão mate no rei roqueado na ala da dama."],["doubleBishopMate","Mate dos dois bispos","Os dois bispos, lado a lado em diagonais, fecham todas as casas do rei."],["dovetailMate","Mate da cauda de andorinha","A dama encosta no rei pela diagonal e as próprias peças dele bloqueiam a fuga."],["hookMate","Mate do gancho","Torre, cavalo e peão formam um gancho: a torre dá mate protegida pelo cavalo."],["deflection","Desvio","Obrigue uma peça defensora a sair do lugar que ela protegia."],["attraction","Atração","Sacrifique para atrair o rei (ou uma peça) para uma casa ruim."],["clearance","Liberação","Tire a sua própria peça do caminho para abrir linha ou casa para outra."],["interference","Interferência","Coloque uma peça entre a defensora e a casa que ela protege."],["intermezzo","Lance intermediário","Antes de recapturar, encaixe um lance mais forte (xeque ou ameaça)."],["xRayAttack","Raio X","Uma peça ataca ou defende através de outra que está na mesma linha."],["capturingDefender","Eliminar o defensor","Capture a peça que segura a defesa; depois o alvo cai."],["trappedPiece","Peça presa","A peça adversária não tem casas de fuga: ataque e ganhe."],["quietMove","Lance silencioso","Sem xeque nem captura, mas cria uma ameaça impossível de parar."],["defensiveMove","Lance defensivo","O melhor lance evita a perda: defenda com precisão."],["zugzwang","Zugzwang","O adversário é obrigado a jogar e qualquer lance piora a posição dele."],["attackingF2F7","Ataque a f2/f7","O ponto mais fraco no começo da partida, defendido só pelo rei."],["exposedKing","Rei exposto","Rei sem proteção de peões: abra linhas e ataque."],["kingsideAttack","Ataque na ala do rei","Ataque ao rei roqueado do lado curto."],["queensideAttack","Ataque na ala da dama","Ataque ao rei roqueado do lado longo."],["advancedPawn","Peão avançado","Um peão perto da promoção decide a partida."],["underPromotion","Subpromoção","Promover a cavalo, torre ou bispo, e não a dama, é o melhor."],["enPassant","En passant","A captura especial do peão que avançou duas casas."],["castling","Roque","O roque é o lance-chave da solução."],["crushing","Esmagador","A solução ganha muito material ou a partida."],["equality","Igualar","Você está pior: ache o lance que salva o equilíbrio."],["pawnEndgame","Final de peões","Rei ativo, oposição e corrida de peões."],["rookEndgame","Final de torres","O final mais comum da prática: torre ativa atrás do peão passado."],["bishopEndgame","Final de bispos","Bispos e peões: cor das casas e rei ativo."],["knightEndgame","Final de cavalos","Cavalos e peões: como os finais de peões, só que com garfos."],["queenEndgame","Final de damas","Damas e peões: xeques perpétuos e peão passado."],["queenRookEndgame","Final de dama e torre","Dama e torre contra dama e torre."],["master","Partidas de mestres","Golpes tirados de partidas de jogadores titulados."],["masterVsMaster","Mestre x mestre","Golpes de partidas entre dois mestres titulados."],["superGM","Supergrandes mestres","Golpes de partidas da elite mundial."]];
